<template><section class="sandbox-form"><div class="field-grid"><label>活动类型<select v-model="form.activityType"><option value="COUPON">优惠券</option><option value="SECKILL">限时秒杀</option><option value="GROUP_BUY">拼团</option><option value="BARGAIN">砍价</option></select></label><label>活动名称<input v-model="form.activityName" placeholder="例如：新生优惠券" /></label><label>优惠值<input v-model.number="form.discountValue" type="number" min="0" step="0.1" placeholder="10" /></label><label>参与商品<input v-model="form.productName" placeholder="例如：校园随行杯" /></label><label>开始时间<input v-model="form.startsAt" type="datetime-local" /></label><label>结束时间<input v-model="form.endsAt" type="datetime-local" /></label></div><div class="activity-note"><strong>{{ typeLabel }}</strong><span>配置结果会随当前工单一并留证，供教师批阅时回溯。</span></div></section></template>
<script setup lang="ts">const props=defineProps<{modelValue:Record<string,unknown>}>(); const emit=defineEmits<{ 'update:modelValue':[Record<string,unknown>]} >(); const form=computed({get:()=>props.modelValue,set:value=>emit('update:modelValue',value)}); const typeLabel=computed(()=>({COUPON:'优惠券活动',SECKILL:'限时秒杀',GROUP_BUY:'拼团活动',BARGAIN:'砍价活动'} as Record<string,string>)[String(form.value.activityType)]??'营销活动'); watch(form,value=>emit('update:modelValue',{...value}),{deep:true})</script>
<style scoped>.sandbox-form{padding:4px}.field-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}label{display:grid;gap:7px;color:#344054;font-size:13px;font-weight:700}input,select{width:100%;box-sizing:border-box;min-height:40px;padding:0 11px;border:1px solid #d0d5dd;border-radius:6px;background:#fff;color:#172033;font:inherit;font-weight:400}.activity-note{display:flex;align-items:center;gap:12px;margin-top:20px;padding:12px;background:#f0fdf4;border-left:3px solid #12b76a;color:#344054;font-size:12px}.activity-note strong{color:#067647;white-space:nowrap}@media(max-width:560px){.field-grid{grid-template-columns:1fr}.activity-note{align-items:flex-start;flex-direction:column;gap:3px}}</style>
